{
  "programmes": [
    {
      "name": "Org-Mol — SINOPEC Research Institute of Petroleum Processing / DP Technology / AI for Science Institute",
      "url": "https://www.nature.com/articles/s41524-025-01720-4",
      "step": "The hand-off from the Org-Mol machine-learning shortlist to synthesis: after screening over 6 million esters and filtering 461 monoesters on predicted dielectric constant, viscosity and thermal conductivity, they pick candidates for synthesis manually. This is exactly the slot where the card inserts Green-Kubo MD verification of viscosity and thermal conductivity before synthesis.",
      "step_url": "https://www.nature.com/articles/s41524-025-01720-4",
      "step_quote": "By further incorporating manual synthetic feasibility assessments based on experimental expertise, we select two candidates for synthesis, and their physical properties are experimentally measured.",
      "activity": {
        "state": "active",
        "claim": "The Org-Mol paper (the source of the 461-monoester shortlist) was published in npj Computational Materials on 11 July 2025; no later release from this collaboration was found.",
        "url": "https://www.nature.com/articles/s41524-025-01720-4",
        "quote": "Published: 11 July 2025"
      },
      "practice": [
        {
          "claim": "The shortlist-to-synthesis step is handled today with machine-learning property models only — the kinetic viscosity model then the thermal conductivity model — with no molecular-dynamics verification in between.",
          "url": "https://www.nature.com/articles/s41524-025-01720-4",
          "quote": "Monoesters with dielectric constants lower than 3.20 are then fed to the kinetic viscosity model and then the thermal conductivity model."
        },
        {
          "claim": "The working shortlist is 461 monoesters, of which only two are actually synthesized and measured; the rest are never independently verified.",
          "url": "https://www.nature.com/articles/s41524-025-01720-4",
          "quote": "Based on the aforementioned criteria of the kinematic viscosity and thermal conductivity, 461 monoesters are finally filtered out."
        },
        {
          "claim": "The team's stated reason for not running MD is cost at screening scale — a claim the card directly tests by parallelising Green-Kubo runs.",
          "url": "https://www.nature.com/articles/s41524-025-01720-4",
          "quote": "It can be seen that predicting these physical properties via MD is time-consuming for a single system and becomes unaffordable in a high-throughput screening scenario with thousands of candidates"
        }
      ],
      "if_lever_changes": "If MD reorders the shortlist, the team would stop selecting two candidates by manual synthetic feasibility from an unverified ML ranking: they would run Green-Kubo viscosity/thermal conductivity over the top 100–300 (or all 461) monoesters and synthesize MD-verified leaders, likely surfacing esters better than the two they measured, and the MD-verified points would become training data to correct the 22.5% MAPE viscosity model.",
      "if_not_changes": "If MD merely confirms the ML ranking unchanged from 100 through 1000 candidates, the published ML-only screening stays as-is and MD is demoted to an optional spot-check, so their practice changes nothing beyond a one-off validation of the pipeline.",
      "already_done": {
        "status": "no",
        "claim": "This team has not run the card's experiment: the 461 monoesters were ranked by ML models and only two were verified, experimentally by synthesis rather than by MD; no Green-Kubo viscosity/thermal conductivity verification of the shortlist was performed.",
        "url": "https://www.nature.com/articles/s41524-025-01720-4",
        "quote": "By further incorporating manual synthetic feasibility assessments based on experimental expertise, we select two candidates for synthesis, and their physical properties are experimentally measured."
      }
    },
    {
      "name": "LG AI Research — GATE (Geometrically Aligned Transfer Encoder)",
      "url": "https://arxiv.org/abs/2510.23371",
      "step": "The final validation stage (Fig. 2f) of their five-stage AI-enabled high-throughput screening workflow for single-phase immersion cooling fluids: after GATE screens billions of candidates down to a shortlist, the chosen few are validated before deployment. The card's MD verification of viscosity and thermal conductivity targets this validation step.",
      "step_url": "https://arxiv.org/html/2510.23371v2",
      "step_quote": "Finally, experimental and literature validation confirm the physicochemical properties of selected candidates (Fig. 2 f), ensuring their suitability as single-phase immersion cooling fluids.",
      "activity": {
        "state": "active",
        "claim": "LG AI Research's GATE immersion-coolant paper was posted to arXiv on 27 October 2025 and last revised 31 October 2025 (v2), the most recent release found.",
        "url": "https://arxiv.org/abs/2510.23371",
        "quote": "[Submitted on 27 Oct 2025 (v1), last revised 31 Oct 2025 (this version, v2)]"
      },
      "practice": [
        {
          "claim": "Validation today is experimental (TGA, DSC) plus literature values; transport properties like viscosity and thermal conductivity that their instruments cannot measure are taken from the literature rather than computed by MD.",
          "url": "https://arxiv.org/html/2510.23371v2",
          "quote": "Decomposition temperature was measured using thermogravimetric analysis (TGA, onset point) and specific heat using differential scanning calorimetry (DSC, 20℃). For other properties that could not be measured with our available instrumentation, we surveyed the literature and incorporated reported values into Fig. 3 d."
        },
        {
          "claim": "The screening operates at billion-molecule scale but narrows to only four experimentally verified candidates, so most shortlisted molecules never get a physics-based check of their viscosity/thermal conductivity.",
          "url": "https://arxiv.org/html/2510.23371v2",
          "quote": "Across the 41 million purchasable compounds and 2.54 billion in-silico reaction products examined, this screening yielded 356 candidates satisfying Criterion 1, and a total of 92,861 compounds meeting at least one of Criteria 1–6."
        },
        {
          "claim": "Four finalists are the extent of their verification stage; the pipeline is run by LG AI Research with Kyonggi University.",
          "url": "https://arxiv.org/html/2510.23371v2",
          "quote": "From these, we selected four final candidates for experimental verification."
        }
      ],
      "if_lever_changes": "If MD reorders a 100–1000 candidate shortlist, LG AI Research would gain a physics-based verification stage to insert between GATE's 92,861-molecule shortlist and its 4-candidate experimental validation — re-ranking viscosity/thermal conductivity by Green-Kubo before purchase/synthesis and catching candidates GATE mis-orders, rather than relying on literature values.",
      "if_not_changes": "If MD only confirms GATE's ranking, the existing literature-plus-TGA/DSC validation remains sufficient and MD verification would not earn a permanent place in their pipeline, so their practice would be unchanged.",
      "already_done": {
        "status": "no",
        "claim": "LG AI Research has not run MD verification of viscosity/thermal conductivity on their shortlist; their validation stage is experimental measurement and literature survey only.",
        "url": "https://arxiv.org/html/2510.23371v2",
        "quote": "Decomposition temperature was measured using thermogravimetric analysis (TGA, onset point) and specific heat using differential scanning calorimetry (DSC, 20℃). For other properties that could not be measured with our available instrumentation, we surveyed the literature and incorporated reported values into Fig. 3 d."
      }
    },
    {
      "name": "Imperial College London Tribology Group (Dini) / Ewen (Bath) — MD-vs-ML thermophysical benchmarking",
      "url": "https://doi.org/10.1039/d6dd00260a",
      "step": "Their head-to-head benchmark of machine-learning models against equilibrium molecular-dynamics (Green-Kubo) simulations for density, viscosity and thermal conductivity of organic liquids (lubricant- and cooling-fluid-sized molecules) — the exact property pair and force-field family the card deploys at shortlist scale.",
      "step_url": "https://spiral.imperial.ac.uk/entities/publication/9423c271-1953-481c-8e8d-88eeb67e2535",
      "step_quote": "In this study, we benchmark ML models for the prediction of the density, viscosity, and thermal conductivity of lubricant-relevant organic liquids, and use MD simulations on a representative subset as an independent, physics-based assessment of the same properties.",
      "activity": {
        "state": "active",
        "claim": "The paper was published in Digital Discovery (RSC) with version of record dated 29 September 2026, a few weeks before this search.",
        "url": "https://pubs.rsc.org/dd/article/doi/10.1039/D6DD00260A/1362876/Benchmarking-Machine-Learning-and-Molecular",
        "quote": "Received: 05 May 2026 Accepted: 18 September 2026 First published: 29 September 2026"
      },
      "practice": [
        {
          "claim": "Their MD practice today is Green-Kubo equilibrium MD on only eight molecules — two each from four chemical families including esters — at 40 and 100 °C, i.e. n=8 rather than the card's 100–1000.",
          "url": "https://spiral.imperial.ac.uk/server/api/core/bitstreams/fa07c113-8958-4f1e-a010-0ef2bfc39e17/content",
          "quote": "Finally, we apply Green–Kubo MD simulations to eight molecules, two from each of the four principal chemical families of the dataset, at 40 °C and 100 °C."
        },
        {
          "claim": "They use the same OPLS-family force field the card specifies, run in LAMMPS.",
          "url": "https://spiral.imperial.ac.uk/server/api/core/bitstreams/fa07c113-8958-4f1e-a010-0ef2bfc39e17/content",
          "quote": "All simulations were performed using the LOPLS-AA force field."
        },
        {
          "claim": "They already found chemistry-dependent force-field error for the property pair the card targets: viscosity is under-predicted for oxygen-containing (ester/ether) molecules, though the reference ranking is largely preserved.",
          "url": "https://spiral.imperial.ac.uk/server/api/core/bitstreams/fa07c113-8958-4f1e-a010-0ef2bfc39e17/content",
          "quote": "Viscosity errors are small for the pure hydrocarbons with LOPLS, but this property is consistently under-predicted for the oxygen-containing molecules; the reference ranking of the fluids is nonetheless largely preserved."
        }
      ],
      "if_lever_changes": "If MD measurably reorders a 100–1000 candidate shortlist, their current conclusion that ML alone is 'well suited to high-throughput screening' would need revision: they would have to recommend MD as a verification stage before synthesis for immersion coolants, contradicting their n=8 finding that MD adds little over ML for ranking.",
      "if_not_changes": "If MD merely confirms the ML ranking, it corroborates their existing result that 'the reference ranking of the fluids is nonetheless largely preserved' by MD — so their practice stays as published: ML for screening, MD only as an extrapolation/force-field sanity check.",
      "already_done": {
        "status": "partly",
        "claim": "This group has already run a smaller version of the card's experiment — Green-Kubo EMD viscosity and thermal conductivity of organic liquids (including esters) benchmarked against ML — but on eight molecules, not a 100–1000 candidate shortlist and not the Org-Mol 461 esters; their finding that LOPLS-AA under-predicts ester viscosity bears directly on the card's OPLS-AA check-first tolerance.",
        "url": "https://spiral.imperial.ac.uk/server/api/core/bitstreams/fa07c113-8958-4f1e-a010-0ef2bfc39e17/content",
        "quote": "Finally, we apply Green–Kubo MD simulations to eight molecules, two from each of the four principal chemical families of the dataset, at 40 °C and 100 °C."
      }
    }
  ],
  "gaps": [
    "No published work runs Green-Kubo viscosity and thermal conductivity over a 100–1000 candidate ester shortlist; the closest prior (Imperial/Dini-Ewen) covers only eight molecules, two of which are esters.",
    "Nobody has MD-verified the Org-Mol 461-monoester ranking, so the card's check-first (OPLS-AA reproducing Ester 1's 6.41 cSt within ±25%) is untested.",
    "LG AI Research validates immersion-coolant candidates by TGA/DSC and literature only, leaving viscosity/thermal conductivity of the ~92,861 shortlist physically unverified before selection.",
    "LOPLS-AA's systematic under-prediction of viscosity for oxygen-containing (ester) molecules is documented at n=8 but unquantified at shortlist scale, so whether MD actually reorders a large ester ranking is genuinely open."
  ],
  "no_programme_reason": ""
}
